// Signs a JSON body for Convex: HMAC-SHA256 over `${timestamp}.${body}`.
// The secret comes from the container env and never appears in workflow JSON
// or execution data (only the resulting signature does).
const crypto = require('crypto');
function signFor(path, payload) {
  const secret = $env.LENDLOOP_N8N_TO_CONVEX_SECRET;
  const base = $env.LENDLOOP_CONVEX_SITE_URL;
  if (!secret || !base) throw new Error('LENDLOOP_N8N_TO_CONVEX_SECRET / LENDLOOP_CONVEX_SITE_URL not set');
  const body = JSON.stringify(payload);
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
  return { url: base.replace(/\/$/, '') + path, body, timestamp, signature };
}

// Error Trigger payload -> a compact, PII-free report for the Convex admin panel.
const { execution = {}, workflow = {} } = $input.first().json;
const report = {
  workflowName: String(workflow.name || 'unknown workflow').slice(0, 200),
  executionId: execution.id ? String(execution.id) : undefined,
  nodeName: execution.lastNodeExecuted ? String(execution.lastNodeExecuted).slice(0, 200) : undefined,
  // Error messages can echo input data, so keep them short.
  message: String((execution.error && execution.error.message) || 'Unknown error').slice(0, 500),
};
console.log('[lendloop] workflow failed', report);
return [{ json: signFor('/n8n/workflow-error', report) }];
